import os
MODULES=['pcc_neuro_ext97','pcc_pediatric_neuro_ext86','pcc_pediatric_surg_ext86']
FUNCS={
'pcc_neuro_ext97':[('HeadacheClinicExt','0.15 + Number(input.freq||10)*0.02 + Number(input.duration||4)*0.05 + Number(input.disability||30)*0.01'),('MigraineProphyExt','0.2 + Number(input.freq||5)*0.04 + Number(input.med||1)*0.15 + Number(input.efficacy||1)*0.15'),('BotoxChronicMigraineExt','0.18 + Number(input.headacheDays||15)*0.01 + Number(input.preBotox||20)*0.005 + Number(input.sites||31)*0.005'),('CGRPAntagonistExt','0.15 + Number(input.drug||1)*0.2 + Number(input.response||1)*0.2 + Number(input.freq||8)*0.02'),('ClusterHeadacheAcuteExt','0.15 + Number(input.oxygen||1)*0.2 + Number(input.triptan||1)*0.2 + Number(input.freq||2)*0.05'),('TensionHeadacheMgmExt','0.15 + Number(input.stress||5)*0.05 + Number(input.relaxation||1)*0.2 + Number(input.responder||1)*0.2'),('TrigeminalNeuralgiaExt','0.15 + Number(input.freq||5)*0.05 + Number(input.carbamazepine||1)*0.2 + Number(input.microvascular||1)*0.2'),('IdiopathicIntracranialHTNExt','0.18 + Number(input.opening||25)*0.01 + Number(input.diamox||1)*0.2 + Number(input.weightLoss||5)*0.04'),('LowCSFPressureExt','0.18 + Number(input.ebp||1)*0.2 + Number(input.bloodPatch||1)*0.2 + Number(input.imaging||1)*0.15'),('ReversibleCerebralVasoconstExt','0.15 + Number(input.segments||3)*0.1 + Number(input.nimodipine||1)*0.2 + Number(input.triggers||1)*0.15')],
'pcc_pediatric_neuro_ext86':[('PediatricHeadacheClinicExt','0.15 + Number(input.freq||5)*0.04 + Number(input.disability||30)*0.01 + Number(input.schoolDays||3)*0.1'),('PediatricMigraineProphyExt','0.2 + Number(input.freq||4)*0.05 + Number(input.med||1)*0.15 + Number(input.response||1)*0.2'),('PediatricChronicMigraineMgmExt','0.18 + Number(input.days||15)*0.01 + Number(input.cbt||1)*0.2 + Number(input.med||1)*0.15'),('PediatricCGRPForMigraineExt','0.15 + Number(input.drug||1)*0.2 + Number(input.response||1)*0.2 + Number(input.weight||40)*0.005'),('PediatricClusterHeadacheExt','0.15 + Number(input.freq||2)*0.1 + Number(input.oxygen||1)*0.2 + Number(input.age||12)*0.02'),('PediatricTensionHeadacheExt','0.15 + Number(input.stress||5)*0.05 + Number(input.relax||1)*0.2 + Number(input.responder||1)*0.2'),('PediatricConcussionHeadacheExt','0.18 + Number(input.days||7)*0.05 + Number(input.symptoms||3)*0.05 + Number(input.sport||1)*0.2'),('PediatricPseudotumorExt','0.18 + Number(input.opening||25)*0.01 + Number(input.diamox||1)*0.2 + Number(input.papilledema||1)*0.2'),('PediatricMigraineMimicsExt','0.15 + Number(input.localizing||1)*0.2 + Number(input.redFlags||1)*0.2 + Number(input.imaging||1)*0.15'),('PediatricIdiopathicStuporExt','0.15 + Number(input.duration||2)*0.15 + Number(input.eeg||1)*0.2 + Number(input.outcome||1)*0.2')],
'pcc_pediatric_surg_ext86':[('PediatricMigraineTriggerSurgExt','0.15 + Number(input.triggers||2)*0.1 + Number(input.surgeryType||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricOccipitalStimExt','0.15 + Number(input.age||12)*0.02 + Number(input.screening||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricMVDDecompressExt','0.15 + Number(input.vessel||1)*0.2 + Number(input.approach||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricCranialStenosisExt','0.18 + Number(input.papilledema||1)*0.2 + Number(input.imaging||1)*0.15 + Number(input.outcome||1)*0.2'),('PediatricEmbolizationAVMExt','0.15 + Number(input.spetzler||2)*0.15 + Number(input.approach||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricTemporalBurrExt','0.15 + Number(input.csf||1)*0.2 + Number(input.burr||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricEndoscopicIIIExt','0.18 + Number(input.age||6)*0.04 + Number(input.tumor||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricChiariDecompressionExt','0.18 + Number(input.tonsils||3)*0.05 + Number(input.syrinx||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricLupusStrokeThrombectomyExt','0.15 + Number(input.lupus||1)*0.2 + Number(input.thrombectomy||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricRevascRevascularExt','0.15 + Number(input.anas||2)*0.1 + Number(input.bypass||1)*0.2 + Number(input.outcome||1)*0.2')]}
for m in MODULES:
    d=f'./{m}'
    os.makedirs(d, exist_ok=True)
    eng=f'// filepath: pcc/{m}/{m}_engine.js\n// {m} engine (deterministic)\nmodule.exports.version=\'v3.196.0\';\nmodule.exports.module=\'{m}\';\nmodule.exports.functions={{}};\n'
    for fn,body in FUNCS[m]:
        eng+=f'module.exports.functions[\'{fn}\']=function(input){{const score=Math.round(({body})*100)/100;return{{version:\'v3.196.0\',module:\'{m}\',function:\'{fn}\',input,score,ts:new Date().toISOString()}};}};\n'
    eng+=f'\n// TS: v3.196.0\n'
    open(f'{d}/{m}_engine.js','w',encoding='utf-8').write(eng)
    test=f'// filepath: pcc/{m}/{m}_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;for(const fn of Object.keys(F)){{const r=F[fn]({{}});if(typeof r.score===\'number\'&&r.score>=0&&r.score<=1.5)pass++;else console.error(\'FAIL\',fn,r);}}console.log(\'{m} unit:\',pass,\'passed\');if(pass!==10)process.exit(1);\n'
    open(f'{d}/{m}_test.js','w',encoding='utf-8').write(test)
    itest=f'// filepath: pcc/{m}/{m}_integration_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;const samples=[{{value:1}},{{value:2}},{{value:3}},{{value:4}},{{value:5}}];for(const fn of Object.keys(F)){{for(const s of samples){{const r=F[fn](s);if(r&&typeof r.score===\'number\')pass++;}}}}console.log(\'{m} integration:\',pass,\'passed\');if(pass!==50)process.exit(1);\n'
    open(f'{d}/{m}_integration_test.js','w',encoding='utf-8').write(itest)
    routes=f'// filepath: pcc/{m}/{m}_routes.js\nconst express=require(\'express\');const {{functions:F}}=require(\'./{m}_engine\');const {{authenticate}}=require(\'../middleware\');const router=express.Router();\nrouter.get(\'/list\',(_req,res)=>res.json({{module:\'{m}\',version:\'v3.196.0\',functions:Object.keys(F)}}));\nrouter.post(\'/call/:fn\',(req,res)=>{{const fn=req.params.fn;if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](req.body||{{}});res.json(r);}});\nrouter.post(\'/record\',(req,res)=>{{const {{fn,payload,decisionId}}=req.body||{{}};if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](payload||{{}});res.json({{decisionId,...r}});}});\nmodule.exports=router;\n'
    open(f'{d}/{m}_routes.js','w',encoding='utf-8').write(routes)
    sql=f'-- pcc/{m}/{m}_up.sql\nIF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N\'[dbo].[{m}]\') AND type = \'U\')\nBEGIN\nCREATE TABLE [dbo].[{m}] (\n  [id] INT IDENTITY(1,1) PRIMARY KEY,\n  [tenant_id] NVARCHAR(64) NOT NULL,\n  [version] NVARCHAR(16) NOT NULL,\n  [module] NVARCHAR(64) NOT NULL,\n  [function] NVARCHAR(128) NOT NULL,\n  [input] NVARCHAR(MAX) NULL,\n  [score] DECIMAL(6,2) NULL,\n  [ts] DATETIME2 DEFAULT SYSUTCDATETIME()\n);\nEND\n'
    open(f'{d}/{m}_up.sql','w',encoding='utf-8').write(sql)
    print(f'{m}: 5 files written')
print('P3-IP v3.196.0: 16 files written')
